<script setup lang="ts">
import { onMounted, onUnmounted, ref } from "vue";
import { useAuth } from "@papilio/auth";
import { item, request, query, type Page, type SmsReceivingRealm, type SmsOriginCapabilities } from "@papilio/api";
import { faDate, faNumber } from "@papilio/ui";
import Modal from "@papilio/ui/Modal.vue";
import ReceivingAliases from "./ReceivingAliases.vue";
const props=defineProps<{capabilities:SmsOriginCapabilities}>();
const auth=useAuth(),base="/v1/admin/payments/sms-origins/receiving-realms";
const rows=ref<SmsReceivingRealm[]>([]),page=ref(1),pages=ref(1),q=ref(""),loading=ref(false),busy=ref(false),error=ref(""),draftError=ref("");
const selected=ref<SmsReceivingRealm|null>(null),open=ref(false),draftReady=ref(false),title=ref(""),active=ref(false),origin=ref(false),expected=ref<number|null>(null),current=ref<SmsReceivingRealm|null>(null);
let alive=true,sequence=0,editorSequence=0;
function message(cause:unknown):string{return cause instanceof Error?cause.message:"The operation failed. Your draft is retained.";}
async function load():Promise<void>{const key=++sequence;loading.value=true;error.value="";try{const result=await request<Page<SmsReceivingRealm>>(`${base}?${query({page:page.value,q:q.value})}`);if(!alive||key!==sequence)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;}catch(cause){if(alive&&key===sequence)error.value=message(cause);}finally{if(alive&&key===sequence)loading.value=false;}}
function create():void{if(busy.value||!props.capabilities.enabled)return;if(selected.value||!draftReady.value){selected.value=null;title.value="";active.value=false;origin.value=false;expected.value=null;current.value=null;draftReady.value=true;}draftError.value="";open.value=true;}
async function edit(row:SmsReceivingRealm):Promise<void>{if(busy.value)return;if(selected.value?.id===row.id&&draftReady.value){open.value=true;return;}const key=++editorSequence;selected.value=row;open.value=true;draftReady.value=false;busy.value=true;draftError.value="";current.value=null;try{const result=await item<SmsReceivingRealm>(`${base}/${row.id}`);if(!alive||key!==editorSequence)return;selected.value=result;expected.value=result.revision;title.value=result.title;active.value=result.is_active;origin.value=result.origin_mode_enabled;draftReady.value=true;}catch(cause){if(alive&&key===editorSequence)draftError.value=message(cause);}finally{if(alive&&key===editorSequence)busy.value=false;}}
async function refreshCurrent():Promise<void>{if(busy.value||!selected.value)return;busy.value=true;draftError.value="";try{const result=await item<SmsReceivingRealm>(`${base}/${selected.value.id}`);if(alive)current.value=result;}catch(cause){if(alive)draftError.value=message(cause);}finally{if(alive)busy.value=false;}}
async function save():Promise<void>{if(!props.capabilities.enabled||busy.value||!draftReady.value||!auth.can("payments",selected.value?"update":"create"))return;busy.value=true;draftError.value="";try{const result=await item<SmsReceivingRealm>(selected.value?`${base}/${selected.value.id}`:base,selected.value?"PUT":"POST",{title:title.value.trim(),is_active:active.value,origin_mode_enabled:origin.value,...(selected.value?{expected_revision:expected.value}:{})});if(!alive)return;selected.value=result;expected.value=result.revision;open.value=false;draftReady.value=false;await load();}catch(cause){if(alive)draftError.value=message(cause);}finally{if(alive)busy.value=false;}}
function originalRequirement(value:number|null):string{if(value===null)return "Not enabled previously";const date=new Date(value);return Number.isFinite(date.getTime())?faDate(date.toISOString()):"Timestamp unavailable";}
onMounted(load);onUnmounted(()=>{alive=false;++sequence;++editorSequence;});
</script>
<template><section class="record-section"><div class="page-head"><div><h3>Receiving accounts</h3><p class="subtitle">Group explicitly associated card, IBAN and account aliases under one stable receiving identity.</p></div><button v-if="capabilities.enabled&&auth.can('payments','create')" class="btn" :disabled="busy" @click="create">Create receiving account</button></div><form class="toolbar" @submit.prevent="page=1;load()"><label class="field"><span>Find receiving account</span><input v-model="q"/></label><button class="btn secondary" :disabled="loading">Search</button></form><p v-if="error" class="message error" role="alert">{{error}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Account</th><th>Revision</th><th>Status</th><th>Origin matching</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.title}}</td><td>{{faNumber(row.revision)}}</td><td>{{row.is_active?'Enabled':'Disabled'}}</td><td>{{row.origin_mode_enabled?'Opted in':'Reference required'}}</td><td><button class="btn small secondary" :disabled="busy" @click="edit(row)">Open account</button></td></tr></tbody></table></div><p v-if="loading" role="status">Loading receiving accounts…</p><p v-else-if="!rows.length&&!error">No receiving accounts found.</p><div class="pager"><button :disabled="loading||page<=1" @click="page--;load()">‹</button><span>{{faNumber(page)}} / {{faNumber(pages)}}</span><button :disabled="loading||page>=pages" @click="page++;load()">›</button></div></section>
<Modal v-model="open" :title="selected?'Receiving account: '+selected.title:'Create receiving account'" :busy="busy" wide><p v-if="draftError" class="message error" role="alert">{{draftError}}</p><p v-if="!draftReady">Loading receiving account…</p><template v-else><div v-if="selected" class="hint-box"><p>Stable receiving identity: <code>{{selected.realm_key}}</code></p><p>Origin metadata requirement first enabled: {{originalRequirement(selected.origin_requirement_since_ms)}}</p></div><form class="form-grid" @submit.prevent="save"><fieldset class="form-grid" :disabled="!capabilities.enabled||busy||!auth.can('payments',selected?'update':'create')"><label class="field"><span>Account title</span><input v-model="title" required maxlength="100"/></label><label class="check-row"><input v-model="active" type="checkbox"/>Receiving account enabled</label><label class="check-row"><input v-model="origin" type="checkbox"/>Allow trusted declared-origin matching</label><p class="hint-box">Opting in requires complete original-source metadata on every automatic SMS approval for this receiving account, including devices that use bank references. Missing metadata remains manual review. Disabling this option does not erase its history or original-source requirement.</p><p>Metadata from an enrolled sender is a declaration, not independent proof of bank settlement. Aliases must be explicitly associated; bank and recipient display names do not establish identity.</p><button class="btn">Save receiving account</button></fieldset></form><div v-if="selected" class="inline-actions"><button class="btn secondary" :disabled="busy" @click="refreshCurrent">Check current revision</button><p v-if="current">Saved revision {{faNumber(current.revision)}}; retained draft targets {{faNumber(expected??0)}}.</p><button v-if="current&&current.revision!==expected&&auth.can('payments','update')" class="btn secondary" :disabled="busy" @click="expected=current.revision">Use reviewed current revision</button></div><ReceivingAliases v-if="selected" :realm-id="selected.id"/></template></Modal></template>
<style scoped>.record-section{margin-top:24px;padding-top:20px;border-top:1px solid var(--line)}code{overflow-wrap:anywhere}fieldset{border:0;padding:0;margin:0;min-width:0}</style>
